/* FOUR IN A ROW - you against Juli. p0pc0rn's example GAME and the showcase of the Game Kit (K.game, part of the p0pc0rn Kit): a moulded
   board with depth, glossy discs that fall with gravity and bounce with a clack and a jolt of the board, a column that lights under your
   finger with a ghost disc, Juli's avatar thinking while her ghost disc wanders, the winning four glowing and pulsing, then confetti, a
   results card with the score across games and a sound switch that is remembered. The discs clear out of the board's bottom before the
   next game.
   Juli plays to win, and every move is her own: on her turn the game reads every legal column (the ENGINE block: a search that looks many
   moves ahead) and gives her that read as a hint, then her model picks one of ALL the legal columns (K.choose) and her answer is her move,
   even a weak one. An answer that names no column is asked again (three times in all); when her model gives no answer the game says so and
   offers "Ask Juli again". The game never moves for her. A game left open goes on next time (K.game.match saves every move), also after
   the page reloads.
   Her opponent is Juli on her own model, always, until the person beats her 10 times in a row (a loss, a draw or a game left half-way
   ends the run; the results card counts it): that unlocks, for good on this phone, the choice of opponent: Juli, or Juli with the
   Bigger brain (only when it is downloaded and on; the same rules, her answer is her move). The PROGRESS block keeps those rules.
   Slots come from window.SLOTS; every slot has a default, so the game also runs with no slots and without window.p0. */

// ===== RULES (pure: the board, the legal moves, the winner, and the facts a player needs; no Kit, no p5) =====
const ROWS = 6, COLS = 7, NAMES = 'ABCDEFG';
const DIRS = [[0, 1], [1, 0], [1, 1], [1, -1]];
/** the board: ROWS rows, top row first; 0 = empty, 1 = the person (X), 2 = Juli (O) */
function emptyBoard() { return Array.from({ length: ROWS }, () => new Array(COLS).fill(0)); }
function legalCols(b) { const out = []; for (let c = 0; c < COLS; c++) if (b[0][c] === 0) out.push(c); return out; }
function dropRow(b, c) { for (let r = ROWS - 1; r >= 0; r--) if (b[r][c] === 0) return r; return -1; }
/** a disc dropped in column c -> {board (a copy), row} or null when the column is full */
function play(b, c, who) { const r = dropRow(b, c); if (r < 0) return null; const nb = b.map((row) => row.slice()); nb[r][c] = who; return { board: nb, row: r }; }
/** does the disc at (r, c) make four in a row for who? */
function fourThrough(b, r, c, who) {
  for (const [dr, dc] of DIRS) {
    let n = 1;
    for (const s of [1, -1]) { let rr = r + dr * s, cc = c + dc * s; while (rr >= 0 && rr < ROWS && cc >= 0 && cc < COLS && b[rr][cc] === who) { n++; rr += dr * s; cc += dc * s; } }
    if (n >= 4) return true;
  }
  return false;
}
/** the winner -> {who, cells: [[r, c] x4]} or null */
function winner(b) {
  for (let r = 0; r < ROWS; r++) for (let c = 0; c < COLS; c++) {
    const w = b[r][c]; if (!w) continue;
    for (const [dr, dc] of DIRS) {
      const cells = [[r, c]];
      for (let k = 1; k < 4; k++) { const rr = r + dr * k, cc = c + dc * k; if (rr < 0 || rr >= ROWS || cc < 0 || cc >= COLS || b[rr][cc] !== w) break; cells.push([rr, cc]); }
      if (cells.length === 4) return { who: w, cells };
    }
  }
  return null;
}
function isFull(b) { return legalCols(b).length === 0; }
/** the columns where who wins with the next disc */
function winsNow(b, who) { return legalCols(b).filter((c) => { const p = play(b, c, who); return !!p && fourThrough(p.board, p.row, c, who); }); }
/** the columns where who's disc would let the other side win right on top of it */
function unsafeCols(b, who) {
  return legalCols(b).filter((c) => { const p = play(b, c, who); if (!p) return false; const q = play(p.board, c, 3 - who); return !!q && fourThrough(q.board, q.row, c, 3 - who); });
}
/** the board as text for Juli: who is who, the rows (top first) and the column letters */
function boardText(b) {
  const sym = ['.', 'X', 'O'];
  return 'Four in a Row: 7 columns (A to G), 6 rows. X = the person, O = you (Juli), . = empty. A disc falls to the lowest empty place '
    + 'in its column. Four in a row across, down or diagonally wins.\nThe board, top row first:\n'
    + b.map((row) => row.map((v) => sym[v]).join(' ')).join('\n') + '\n' + NAMES.split('').join(' ');
}
/** Juli's options: the legal columns, in order */
function optionsFor(b) { return legalCols(b).map((c) => 'column ' + NAMES[c]); }
/** a short hint for `me` from the facts alone: a win now, else a block, else a column to avoid and a good one near the middle (each with
 *  its choice's number; the benchmark's positions use it) */
function hintFor(b, me) {
  const legal = legalCols(b), name = (c) => 'column ' + NAMES[c] + ' (choice ' + (legal.indexOf(c) + 1) + ')', list = (cs) => cs.map(name).join(' or ');
  const win = winsNow(b, me); if (win.length) return name(win[0]) + ' wins now for you: take it.';
  const threat = winsNow(b, 3 - me); if (threat.length) return 'The person wins next in ' + list(threat) + ': block ' + (threat.length > 1 ? 'one.' : 'it.');
  const bad = legal.length > 1 ? unsafeCols(b, me) : [];
  const mid = [3, 2, 4, 1, 5, 0, 6].filter((c) => legal.includes(c) && !bad.includes(c));
  return (bad.length ? 'Avoid ' + list(bad) + ': the person would win right on top of your disc. ' : '')
    + 'No win or block now. The middle columns are strongest' + (mid.length ? ': ' + name(mid[0]) + ' is a good choice.' : '.');
}
/** a simple player's move for `me` (the benchmark's reference): win, else block, else a safe column nearest the middle */
function ownMove(b, me) {
  const legal = legalCols(b); if (!legal.length) return -1;
  const win = winsNow(b, me); if (win.length) return win[0];
  const threat = winsNow(b, 3 - me); if (threat.length) return threat[0];
  const bad = unsafeCols(b, me), order = [3, 2, 4, 1, 5, 0, 6];
  const safe = order.find((c) => legal.includes(c) && !bad.includes(c));
  return safe != null ? safe : order.find((c) => legal.includes(c));
}
const MIDDLE_FIRST = [3, 2, 4, 1, 5, 0, 6];
/** a plain score of the board for `me` (a small look-ahead player for tests, through the Game Kit's search): every run of four cells
 *  that only one side can still fill counts (three of it: 5, two: 2), and a disc in the middle column 3; the other side's the same, taken off */
function evaluate(b, me) {
  const op = 3 - me; let s = 0;
  for (let r = 0; r < ROWS; r++) s += b[r][3] === me ? 3 : b[r][3] === op ? -3 : 0;
  for (const [dr, dc] of DIRS) for (let r = 0; r < ROWS; r++) for (let c = 0; c < COLS; c++) {
    const r3 = r + 3 * dr, c3 = c + 3 * dc; if (r3 < 0 || r3 >= ROWS || c3 < 0 || c3 >= COLS) continue;
    let m = 0, o = 0;
    for (let k = 0; k < 4; k++) { const v = b[r + k * dr][c + k * dc]; if (v === me) m++; else if (v === op) o++; }
    if (m && o) continue;
    s += m === 3 ? 5 : m === 2 ? 2 : 0; s -= o === 3 ? 5 : o === 2 ? 2 : 0;
  }
  return s;
}
/** the game as the Game Kit's search sees it: b is searched IN PLACE (pass a copy); columns middle-first; a disc in and out; a four;
 *  a full top row; the score for the side to move */
function searchSpec(b, me) {
  return { state: b, who: me, moves: (s) => MIDDLE_FIRST.filter((c) => s[0][c] === 0),
    do: (s, c, w) => { const r = dropRow(s, c); s[r][c] = w; return r; }, undo: (s, c, r) => { s[r][c] = 0; },
    won: (s, c, r, w) => fourThrough(s, r, c, w), draw: (s) => s[0].every((v) => v !== 0), score: (s, w) => evaluate(s, w) };
}
// ===== END RULES =====

// ===== ENGINE (pure: the game's own read of every column, the hint Juli gets; no Kit, no p5) =====
// A bitboard search (Pascal Pons' layout: bit = column * 7 + row, row 0 at the bottom, one spare bit on top of each column) in two 32-bit
// words (JS bit operations are 32-bit), negamax with alpha-beta, a transposition table, the moves that make the most threats first (then
// the middle), deepening one level at a time while its time lasts, and a small opening book. It never moves for Juli: it reads the board.
// C4E.read(board, me, {timeMs, maxNodes, now}) -> a job: job.step(sliceMs) works for at most sliceMs and returns true when the read is
// finished (the game calls it once a frame, so the frames keep flowing); job.result() -> [{c, v, d, exact}] for every legal column:
// v > C4E.MATE = me wins in C4E.WIN - v plies, v < -C4E.MATE = the other side wins in C4E.WIN + v plies, else the search's estimate.
const C4E = (() => {
  const W = 7, H = 6, WIN = 1000, MATE = 900, INF = 30000;
  const ORDER = [3, 2, 4, 1, 5, 0, 6];
  const bit = (c, r) => c * 7 + r;
  let BL = 0, BH = 0, ODL = 0, ODH = 0, EVL = 0, EVH = 0;
  // each cell's worth: how many lines of four pass through it (the middle is worth most)
  const LINES = [[3, 4, 5, 7, 5, 4, 3], [4, 6, 8, 10, 8, 6, 4], [5, 8, 11, 13, 11, 8, 5], [5, 8, 11, 13, 11, 8, 5], [4, 6, 8, 10, 8, 6, 4], [3, 4, 5, 7, 5, 4, 3]];
  const WT = new Int8Array(49);
  for (let c = 0; c < W; c++) for (let r = 0; r < H; r++) {
    const i = bit(c, r), lo = i < 32, m = lo ? 1 << i : 1 << (i - 32); WT[i] = LINES[r][c];
    if (lo) BL |= m; else BH |= m;
    if (r % 2 === 0) { if (lo) ODL |= m; else ODH |= m; } else if (lo) EVL |= m; else EVH |= m;   // odd rows counted from 1 at the bottom
  }
  // the position: P = the stones of the side to move, M = every stone, T = each column's height, N = stones played
  let PL = 0, PH = 0, ML = 0, MH = 0, N = 0, CW = 0;   // CW = the worth of the first mover's stones less the other's
  const T = new Int8Array(W);
  let RL = 0, RH = 0;   // winCells' answer
  const pop = (x) => { x -= (x >>> 1) & 0x55555555; x = (x & 0x33333333) + ((x >>> 2) & 0x33333333); return Math.imul((x + (x >>> 4)) & 0x0f0f0f0f, 0x01010101) >>> 24; };
  /** the empty cells where the stones p (lo, hi) would make four (Pons' compute_winning_position) -> RL, RH */
  function winCells(pL, pH, mL, mH) {
    let rL = (pL << 1) & (pL << 2) & (pL << 3);
    let rH = ((pH << 1) | (pL >>> 31)) & ((pH << 2) | (pL >>> 30)) & ((pH << 3) | (pL >>> 29));
    for (let k = 6; k <= 8; k++) {
      const k2 = k << 1, k3 = k * 3;
      const a1L = pL << k, a1H = (pH << k) | (pL >>> (32 - k)), a2L = pL << k2, a2H = (pH << k2) | (pL >>> (32 - k2));
      const a3L = pL << k3, a3H = (pH << k3) | (pL >>> (32 - k3));
      const b1L = (pL >>> k) | (pH << (32 - k)), b1H = pH >>> k, b2L = (pL >>> k2) | (pH << (32 - k2)), b2H = pH >>> k2;
      const b3L = (pL >>> k3) | (pH << (32 - k3)), b3H = pH >>> k3;
      let tL = a1L & a2L, tH = a1H & a2H;
      rL |= (tL & a3L) | (tL & b1L); rH |= (tH & a3H) | (tH & b1H);
      tL = b1L & b2L; tH = b1H & b2H;
      rL |= (tL & a1L) | (tL & b3L); rH |= (tH & a1H) | (tH & b3H);
    }
    RL = rL & BL & ~mL; RH = rH & BH & ~mH;
  }
  function play(c) { const i = bit(c, T[c]++); PL ^= ML; PH ^= MH; if (i < 32) ML |= 1 << i; else MH |= 1 << (i - 32); CW += N & 1 ? -WT[i] : WT[i]; N++; }
  function unplay(c) { const i = bit(c, --T[c]); if (i < 32) ML &= ~(1 << i); else MH &= ~(1 << (i - 32)); PL ^= ML; PH ^= MH; N--; CW -= N & 1 ? -WT[i] : WT[i]; }
  const onCell = (L, Hh, c) => { const i = bit(c, T[c]); return i < 32 ? (L >>> i) & 1 : (Hh >>> (i - 32)) & 1; };

  // the transposition table: slot = the key mod a prime, check = the key mod 2^32 (the two together name one position)
  const TN = 524287;
  const tK = new Uint32Array(TN), tV = new Int16Array(TN), tD = new Int8Array(TN), tF = new Uint8Array(TN), tM = new Int8Array(TN);
  let kSlot = 0, kCheck = 0;
  function key() { const lo = (PL >>> 0) + (ML >>> 0), k = (PH + MH) * 4294967296 + lo; kSlot = k % TN; kCheck = lo >>> 0; }

  // a guess at the depth limit, for the side to move. What decides a four-in-a-row endgame is who owns the lowest threat in each column
  // and on which row (Allis: odd rows, counted from 1 at the bottom, suit the side that moved first; even rows the other): such a cell is
  // worth much (30), a threat on the other parity little (8); every other cell that would make four a little more (2); and each stone's
  // worth (the lines of four through its cell)
  function guess(mwL, mwH, owL, owH) {
    const first = (N & 1) === 0;   // the side to move made the first move
    let s = 2 * (pop(mwL) + pop(mwH) - pop(owL) - pop(owH));
    for (let c = 0; c < W; c++) {
      for (let r = T[c]; r < H; r++) {
        const i = bit(c, r), lo = i < 32, m = lo ? (mwL >>> i) & 1 : (mwH >>> (i - 32)) & 1, o = lo ? (owL >>> i) & 1 : (owH >>> (i - 32)) & 1;
        if (!(m | o)) continue;
        const odd = (r & 1) === 0;   // row r + 1 counted from the bottom is odd
        if (m) s += (odd === first) ? 30 : 8;
        if (o) s -= (odd !== first) ? 30 : 8;
        break;   // the lowest threat in the column decides it
