    }
    return s + (first ? CW : -CW);
  }

  let nodes = 0, stopAt = 0, capAt = 0, clock = () => Date.now();
  const ABORT = { abort: true };
  const MV = new Int8Array(64 * 8), SC = new Int8Array(64 * 8);
  /** negamax with alpha-beta from the side to move; ply = plies from the read's position (mate scores count from there) */
  function search(depth, alpha, beta, ply) {
    if ((++nodes & 1023) === 0 && ((stopAt && clock() > stopAt) || (capAt && nodes > capAt))) throw ABORT;
    if (N >= 42) return 0;
    let posL = 0, posH = 0;
    for (let c = 0; c < W; c++) { const h = T[c]; if (h < H) { const i = bit(c, h); if (i < 32) posL |= 1 << i; else posH |= 1 << (i - 32); } }
    winCells(PL, PH, ML, MH); const mwL = RL, mwH = RH;
    if ((mwL & posL) | (mwH & posH)) return WIN - ply - 1;                        // a four now
    winCells(PL ^ ML, PH ^ MH, ML, MH); const owL = RL, owH = RH;
    const fL = posL & owL, fH = posH & owH;
    if (fL | fH) { if (pop(fL) + pop(fH) > 1) return -(WIN - ply - 2); posL = fL; posH = fH; }   // two of theirs: lost; one: block it
    const cL = posL & ~((owL >>> 1) | (owH << 31)), cH = posH & ~(owH >>> 1);     // never right under a cell that makes their four
    if (!(cL | cH)) return -(WIN - ply - 2);
    if (N >= 41) return 0;                                                          // the last cell: a draw
    if (depth <= 0) return guess(mwL, mwH, owL, owH);
    key(); const slot = kSlot, chk = kCheck;
    let ttMove = -1;
    if (tF[slot] && tK[slot] === chk) {
      ttMove = tM[slot];
      if (tD[slot] >= depth) {
        let v = tV[slot]; if (v > MATE) v -= ply; else if (v < -MATE) v += ply;
        const f = tF[slot];
