    }
    // the moves: the table's best first, then those that make the most cells for a four, then the middle
    const base = ply << 3; let n = 0;
    for (let k = 0; k < W; k++) {
      const c = ORDER[k]; if (T[c] >= H || !onCell(cL, cH, c)) continue;
      let s;
      if (c === ttMove) s = 100;
      else { const i = bit(c, T[c]); if (i < 32) winCells(PL | (1 << i), PH, ML, MH); else winCells(PL, PH | (1 << (i - 32)), ML, MH); s = pop(RL) + pop(RH); }
      let j = n++; while (j > 0 && SC[base + j - 1] < s) { MV[base + j] = MV[base + j - 1]; SC[base + j] = SC[base + j - 1]; j--; }
      MV[base + j] = c; SC[base + j] = s;
    }
    const a0 = alpha; let best = -INF, bestC = -1;
    for (let k = 0; k < n; k++) {
      const c = MV[base + k];
      play(c); const v = -search(depth - 1, -beta, -alpha, ply + 1); unplay(c);
      if (v > best) { best = v; bestC = c; if (v > alpha) { alpha = v; if (alpha >= beta) break; } }
    }
    let sv = best; if (sv > MATE) sv += ply; else if (sv < -MATE) sv -= ply;
    tK[slot] = chk; tV[slot] = sv; tD[slot] = depth; tM[slot] = bestC; tF[slot] = best <= a0 ? 3 : best >= beta ? 2 : 1;
    return best;
  }

  function setBoard(b, me) {
    const n = b.reduce((a, row) => a + row.filter(Boolean).length, 0), firstOf = n % 2 === 0 ? me : 3 - me;   // who made the first move
    PL = PH = ML = MH = 0; N = 0; CW = 0;
    for (let c = 0; c < W; c++) {
      let h = 0;
      for (let r = H - 1; r >= 0 && b[r][c]; r--, h++) {
        const i = bit(c, h), m = i < 32 ? 1 << i : 1 << (i - 32); N++;
        if (i < 32) { ML |= m; if (b[r][c] === me) PL |= m; } else { MH |= m; if (b[r][c] === me) PH |= m; }
