    }
  }
  /** a board's book key for the side to move: each column's stones from the bottom (x = the side to move, o = the other), joined by '/' */
  const bookKey = (b, me) => { const out = []; for (let c = 0; c < W; c++) { let s = ''; for (let r = H - 1; r >= 0 && b[r][c]; r--) s += b[r][c] === me ? 'x' : 'o'; out.push(s); } return out.join('/'); };
  // the opening book: bookKey -> [[column, result with best play from both: 1 win, 0 draw, -1 loss], ...] for the side to move. The first
  // move is solved (Allis 1988, Tromp 1995): the middle column wins for the side that starts, the two beside it draw, the rest lose
  const BOOK = { '//////': [[3, 1], [2, 0], [4, 0], [1, -1], [5, -1], [0, -1], [6, -1]] };
  const BOOKV = 800;   // a book result's place in the order: above every estimate, below a forced result the search found

  /** a read of every legal column of b (rows top first; 0 empty, 1 and 2 the players) for `me`, the side to move */
  function read(b, me, o) {
    o = o || {}; setBoard(b, me);
    const root = { PL, PH, ML, MH, N, CW, T: Array.from(T) };
    const restore = () => { PL = root.PL; PH = root.PH; ML = root.ML; MH = root.MH; N = root.N; CW = root.CW; for (let c = 0; c < W; c++) T[c] = root.T[c]; };
    const cols = ORDER.filter((c) => T[c] < H), empties = 42 - N, res = new Map(), job = { done: false, depth: 0, nodes: 0, ms: 0, book: false };
