    const cur = new Map(), maxDepth = Math.min(o.maxDepth || 42, empties);
    job.step = (sliceMs) => {
      if (job.done) return true;
      if (o.now) clock = o.now;
      const t0 = clock(); stopAt = sliceMs ? t0 + sliceMs : 0; const n0 = nodes; capAt = o.maxNodes ? nodes + Math.max(1, o.maxNodes - job.nodes) : 0;
      try {
        for (;;) {
          if (i >= order.length) {
            for (const [c, v] of cur) { const r = res.get(c); if (!r.exact) { r.v = v; r.d = d; r.exact = d >= empties; } }
            cur.clear(); job.depth = d;
            if (d >= maxDepth || cols.every((c) => res.get(c).exact)) { job.done = true; break; }
            d++; i = 0; order = cols.slice().sort((x, y) => res.get(y).v - res.get(x).v);
          }
          const c = order[i], r = res.get(c);
          if (r.exact) { i++; continue; }
          play(c); const v = -search(d - 1, -INF, INF, 1); restore();
          if (Math.abs(v) > MATE) { r.v = v; r.d = d; r.exact = true; } else cur.set(c, v);
          i++;
