      job.nodes += nodes - n0; job.ms += clock() - t0; stopAt = 0; capAt = 0;
      if ((o.timeMs && job.ms >= o.timeMs) || (o.maxNodes && job.nodes >= o.maxNodes)) job.done = true;
      return job.done;
    };
    job.result = () => cols.map((c) => Object.assign({}, res.get(c)));
