  function readNow(b, me, o) { o = o || {}; const j = read(b, me, o); while (!j.step(o.timeMs || 0)) { /* until the budget or the end */ } return { cols: j.result(), depth: j.depth, nodes: j.nodes, ms: j.ms, book: j.book }; }
  const clearTable = () => { tF.fill(0); };
  /** the game's result after `me` plays column c with best play by both (1 win, 0 draw, -1 loss), or null past the budget (makes the book) */
  function solveCol(b, me, c, o) {
    o = o || {}; setBoard(b, me);
    winCells(PL, PH, ML, MH); if (onCell(RL, RH, c)) return 1;
    const n0 = nodes; capAt = o.maxNodes ? nodes + o.maxNodes : 0; stopAt = 0;
    try { play(c); const v = -search(42 - N, -1, 1, 1); return v > 0 ? 1 : v < 0 ? -1 : 0; }
    catch (e) { if (e !== ABORT) throw e; return null; }
    finally { capAt = 0; void n0; }
  }
  return { read, readNow, clearTable, bookKey, solveCol, BOOK, WIN, MATE, ORDER };
})();
// ===== END ENGINE =====

// ===== PROGRESS (pure: the run of wins against Juli, the unlock it earns, the opponent to choose; no Kit, no p5) =====
const UNLOCK_AT = 10;
/** the saved progress (the match's st.keep), checked: run = wins in a row against Juli on her own model; unlocked = the choice of
 *  opponent, earned once and kept on this phone; opp = the chosen opponent ('juli', or 'big' = Juli with the Bigger brain, only once
 *  unlocked); fresh = the unlock just happened (its card is still to show) */
function keepOf(k) {
  k = k && typeof k === 'object' ? k : {};
  const unlocked = k.unlocked === true;
  return { run: Math.max(0, Math.min(9999, Math.floor(+k.run || 0))), unlocked, opp: unlocked && k.opp === 'big' ? 'big' : 'juli', fresh: unlocked && k.fresh === true };
}
/** the progress after a game against `opp` ('juli', 'big', or 'mixed': the opponent changed during it) that `who` won (1 the person,
 *  2 Juli, 0 a draw): a win against Juli on her own model adds one to the run, a loss or a draw ends it, and the run's 10th win unlocks
 *  the choice of opponent (once, for good). A game against the Bigger brain leaves the run as it was. */
function afterGame(k, opp, who) {
  const n = keepOf(k);
  if (opp !== 'juli') return n;
  if (who !== 1) { n.run = 0; return n; }
  n.run += 1;
  if (!n.unlocked && n.run >= UNLOCK_AT) { n.unlocked = true; n.fresh = true; }
  return n;
}
/** a game left for a new one (New game, another opponent) after it started: for the run it counts as a loss when it was against Juli */
function afterQuit(k, opp, started) { const n = keepOf(k); if (started && opp === 'juli') n.run = 0; return n; }
/** the results card's run toward the unlock -> {n, of, text}, or null (earned already, or a game against the Bigger brain) */
function progressOf(k, opp) {
  const n = keepOf(k); if (n.unlocked || opp !== 'juli') return null;
  const run = Math.min(n.run, UNLOCK_AT - 1);
  return { n: run, of: UNLOCK_AT, text: run ? run + ' in a row: ' + (UNLOCK_AT - run) + ' more to unlock a new opponent' : 'Win ' + UNLOCK_AT + ' in a row to unlock a new opponent' };
}
/** the menu's choice of opponent -> its rows: none before the unlock; Juli always; the Bigger brain selectable only when it is
 *  downloaded and on (big = K.juliModels().big) */
function opponentRows(k, big, juli) {
  const n = keepOf(k); if (!n.unlocked) return [];
  return [{ id: 'juli', title: juli, sub: 'Her own model: quick moves', on: n.opp === 'juli', can: true },
    { id: 'big', title: juli + ' with the Bigger brain', sub: big ? 'Slower moves: she reads the board more deeply' : 'Off: Settings › Models & downloads', on: n.opp === 'big', can: !!big }];
}
// ===== END PROGRESS =====

// ===== SLOTS =====
const SL = window.SLOTS || {};
const hex = (v, d) => (/^#[0-9a-fA-F]{6}$/.test(v || '') ? v : d);
const TITLE = String(SL.title || 'Four in a Row').slice(0, 22) || 'Four in a Row';
const YOU = String(SL.player_name || 'You').slice(0, 14) || 'You';
const JULI = String(SL.juli_name || 'Juli').slice(0, 14) || 'Juli';
const C_YOU = hex(SL.player_color, '#ff4757'), C_JULI = hex(SL.juli_color, '#ffc43a'), C_BOARD = hex(SL.board_color, '#5b34c9');
const FIRST = ['you', 'juli', 'take turns'].includes(SL.first) ? SL.first : 'take turns';
const WIN_TEXT = String(SL.win_text || 'You win!').slice(0, 40);
const JULI_WIN_TEXT = String(SL.juli_win_text || 'Juli wins').slice(0, 40);
const SKILL = 'play-four-in-a-row';
const G = K.game;
const colorOf = (who) => (who === 1 ? C_YOU : C_JULI);

// ===== JULI'S MOVES: the game reads the board, she chooses =====
// THE HINT SWITCH: true = Juli's prompt carries the game's read of every column (the engine below, about 1.2 s inside "Juli is thinking");
// false = she plays on her own reading of the board. Either way she picks from every legal column and her answer is her move.
const GAME_HINTS = true;
const READ_MS = 1200, READ_WALL_MS = 1700, HONEST = JULI + ' plays to win. Every move is her own.';
// the read beside each choice too ("3. column C (wins now)"): a small model ties a number to its outcome better there than in a hint above
const READ_IN_CHOICES = true;
let lastRead = null;
const moveLog = [];   // Juli's moves with the read she had (the desk's measurements read it through window.__c4)
/** what HER move in one column leads to, in a few plain words (a small model read "they win next" as "block there": every read says
 *  what her own choice does) */
function readWord(r) {
  if (r.book) return r.book === 'win' ? 'wins with best play' : r.book === 'loss' ? 'loses with best play' : 'draws with best play';
  if (r.v > C4E.MATE) { const n = (C4E.WIN - r.v + 1) >> 1; return n <= 1 ? 'wins now' : 'wins in ' + n + ' moves'; }
  if (r.v < -C4E.MATE) { const n = (C4E.WIN + r.v) >> 1; return n <= 1 ? 'loses at once' : 'loses in ' + n + ' moves'; }
  return r.exact ? 'draws' : 'even';
}
/** the read in plain words, best first, the same reads said once: "what each choice leads to, best first: wins now: 3 (C); even: ..." */
function readText(read, legal) {
  const list = read.slice().sort((a, b) => b.v - a.v || MIDDLE_FIRST.indexOf(a.c) - MIDDLE_FIRST.indexOf(b.c)), groups = [];
  for (const r of list) { const w = readWord(r), g = groups[groups.length - 1]; if (g && g.w === w) g.cs.push(r.c); else groups.push({ w, cs: [r.c] }); }
  return 'what each choice leads to, best first: ' + groups.map((g) => g.w + ': ' + g.cs.map((c) => (legal.indexOf(c) + 1) + ' (' + NAMES[c] + ')').join(', ')).join('; ');
}
/** her turn: the game's read (sliced, so the frames keep flowing), then EVERY legal column as her options */
async function juliAsk(b, legal) {
  let read = null;
  if (GAME_HINTS) {
    const job = C4E.read(b, 2, { timeMs: READ_MS, now: () => performance.now() });
    await G.work((ms) => job.step(ms), { sliceMs: 10, wallMs: READ_WALL_MS });
    read = job.result();
    lastRead = { board: G.copy(b), read, depth: job.depth, nodes: job.nodes, ms: Math.round(job.ms), book: !!job.book };
  } else lastRead = { board: G.copy(b), read: null };
  const word = read && READ_IN_CHOICES ? new Map(read.map((r) => [r.c, readWord(r)])) : null;
  return { about: boardText(b), skill: SKILL, options: legal.map((c) => ({ move: c, label: 'column ' + NAMES[c] + (word ? ' (' + word.get(c) + ')' : '') })), hint: read ? readText(read, legal) : '' };
}

// ===== THE MATCH (turns, save and resume, score: the Game Kit) =====
const M = G.match({
  key: 'c4.v1', first: FIRST,
  fresh: emptyBoard,
  legal: (b) => legalCols(b),
  valid: (b) => b.length === ROWS && b.every((r) => Array.isArray(r) && r.length === COLS && r.every((v) => v === 0 || v === 1 || v === 2)),
  apply: (b, c, who) => { const p = play(b, c, who); return { board: p.board, last: [p.row, c] }; },
  result: (b, c, who, a) => {
    if (fourThrough(b, a.last[0], c, who)) { const l = G.lineAt(b, a.last[0], c, 4); return { who, cells: l ? l.cells : (winner(b) || { cells: [] }).cells }; }
    return isFull(b) ? { who: 0, cells: [] } : null;
  },
  animate: (c, who, a) => dropDisc(c, a.last[0], who),
  juli: {
    ask: juliAsk, minMs: 650, tries: 3,
    // her model answers with one of the options, on this phone; big = the earned opponent, Juli with the Bigger brain (the same rules:
    // her answer is her move)
    pick: (a) => K.choose(a.about, a.options, { skill: a.skill, hint: a.hint, big: gameOpp() === 'big' }),
    beforeMove: (c) => glideTo(c),
  },
  tally: (st, who) => { st.keep = afterGame(st.keep, st.opp || 'juli', who); },   // the run of wins and the unlock, saved with the score
});
/** this game's opponent: 'juli' (her own model), 'big' (Juli with the Bigger brain) or 'mixed' (it changed during the game) */
const gameOpp = () => (M.st && (M.st.opp === 'big' || M.st.opp === 'mixed') ? M.st.opp : 'juli');
const BIG = JULI + ' with the Bigger brain';
const oppName = (o) => (o === 'big' ? BIG : JULI);
let bigOK = null;   // the Bigger brain downloaded and on (K.juliModels), checked when the game starts and when the menu opens
const checkBig = () => (K.juliModels ? K.juliModels().then((m) => (bigOK = !!(m && m.big))).catch(() => (bigOK = false)) : Promise.resolve((bigOK = false)));

// ===== LAYOUT (portrait first; it fits any size): the players on top, the board in the middle, the controls at the bottom (the thumb) =====
let LY = null;
function geo() {
  const W = K.W, H = K.H;
  if (LY && LY.W === W && LY.H === H) return LY;
  const phone = /iPhone|iPad|Android/.test(navigator.userAgent || '');
  const top = Math.max(K.safe.top, 8) + 6, bot = Math.max(K.safe.bottom, phone ? 26 : 14), side = W >= 600 ? 28 : 14;   // the bottom stays clear of the home bar
  const playersH = H > 700 ? 66 : 58, statusH = H > 700 ? 48 : 38, barH = 50, footH = 30;
  const byW = Math.floor((Math.min(W - 2 * side, 600) - 2 * 14) / COLS);
  const byH = Math.floor((H - top - bot - playersH - statusH - barH - footH - 24) / (ROWS + 1.75));
  const cell = Math.max(24, Math.min(byW, byH, 84)), pad = Math.round(Math.max(8, cell * 0.24));
  const bw = cell * COLS + 2 * pad, bh = cell * ROWS + 2 * pad, feet = Math.round(cell * 0.42);
  const players = { y: top, h: playersH - 6 }, status = { y: top + playersH + statusH * 0.6 };
  const bar = { y: H - bot - barH + 4 }, foot = bar.y - 12;
  const free = foot - footH - (top + playersH + statusH), laneH = Math.round(cell * (free > cell * 9 ? 1.3 : 1.1));   // a tall phone: a deeper lane
  const blockH = laneH + bh + feet, y0 = top + playersH + statusH + Math.max(0, Math.round((free - blockH) * 0.32));
  const lane = { y: y0 + laneH / 2 };
  const L = G.layout({ rows: ROWS, cols: COLS, x: (W - bw) / 2, y: y0 + laneH, w: bw, h: bh, pad, align: 'top' });
  LY = { W, H, top, bot, side, players, status, bar, lane, L, foot: Math.max(L.y + L.h + feet + 22, foot), hole: cell * 0.4, disc: cell * 0.445 };
  return LY;
}

// ===== MOTION: the drop, Juli's ghost, the clear-out =====
let anim = null, clearing = null, landFx = null, ghostJ = null;
function dropDisc(c, row, who) {
  const g = geo(), L = g.L;
  return new Promise((res) => {
    const body = G.fall({ from: g.lane.y, to: L.cy(row), g: Math.max(1500, L.cell * 125) * (G.reduced ? 2.4 : 1), bounce: G.reduced ? 0 : 0.24, minHop: 1.4,
      onHit: (speed, n, k) => {
        G.sound.play('clack', { vel: n === 1 ? 0.5 + 0.5 * k : 0.22 * k, pitch: who === 1 ? 1 : 0.88 });
        if (n === 1) { G.jolt('board', 0.8 + 2.4 * k); landFx = { c, row, who, t0: K.t }; }
      },
      onDone: () => { anim = null; res(); } });
    anim = { c, row, who, body };
    G.hot(900);
  });
}
/** Juli decided: her ghost glides over to the column, then the disc falls */
function glideTo(c) {
  const L = geo().L; if (!ghostJ) ghostJ = { x: L.cx(3) };
  ghostJ.target = c;
  if (G.reduced) { ghostJ.x = L.cx(c); return Promise.resolve(); }
  return G.timeline().tween(ghostJ, { x: L.cx(c) }, 240, { ease: 'outCubic' }).wait(60).play();
}
/** the next game: the discs fall out of the bottom of the board, column by column (a disc still falling goes from where it is) */
function clearBoard() {
  const g = geo(), L = g.L, b = M.st.board, list = [], fall = anim, fy = fall ? fall.body.y : 0;
  if (fall) { anim = null; fall.body.skip(); }   // its move ends here: the match drops the rest of it (a new game is coming)
  for (let c = 0; c < COLS; c++) for (let r = ROWS - 1; r >= 0; r--) if (b[r][c]) list.push({ c, who: b[r][c], y: fall && fall.c === c && fall.row === r ? fy : L.cy(r), body: null, at: c * 36 + (ROWS - 1 - r) * 22 });
  if (!list.length || G.reduced) return Promise.resolve();
  clearing = list; G.sound.play('clear'); G.hot(1600);
  const tl = G.timeline();
  for (const d of list) tl.call(() => { d.body = G.fall({ from: d.y, to: K.H + L.cell * 2, g: L.cell * 70, bounce: 0 }); }, { at: d.at });
  return tl.play().then(() => Promise.all(list.map((d) => (d.body ? d.body.promise : null)))).then(() => { clearing = null; });
}

// ===== STATE OF THE SCREEN =====
let resultsOpen = false, againPill = false, menuOpen = false, endFx = null, startScore = null, touched = false, busyNew = false, unlockOpen = false;
const say = (t) => G.a11y.say(t);
/** what the game says when Juli gives no move (it never moves for her): plain words, then "Ask Juli again" */
const STUCK_TEXT = { stopped: JULI + '’s model stopped', unreadable: JULI + ' didn’t name a column', busy: JULI + ' is busy with another job',
  missing: JULI + ' isn’t downloaded on this phone yet', nojuli: JULI + ' plays inside p0pc0rn', notallowed: JULI + ' isn’t allowed to play here',
  ratelimit: JULI + ' needs a short break', bad: JULI + ' can’t play here', dropped: JULI + '’s model stopped',
  nobig: 'The Bigger brain is off' };   // the line under it says where to turn it on
const stuckText = () => (!M.stuck ? '' : gameOpp() === 'big' && /^(stopped|dropped)$/.test(M.stuck.kind) ? 'The Bigger brain stopped' : STUCK_TEXT[M.stuck.kind] || STUCK_TEXT.stopped);
M.on('new', (e) => {
  M.st.opp = keepOf(M.st.keep).opp; M.save();   // this game's opponent (it changes between games only)
  endFx = null; resultsOpen = false; againPill = false; unlockOpen = false; ghostJ = null; startScore = Object.assign({}, M.st.score); if (!e.quiet) G.sound.play('start');
  G.a11y.title(TITLE + ': you against ' + oppName(gameOpp()));
  say(e.turn === 1 ? 'New game. Your turn.' : 'New game. ' + oppName(gameOpp()) + ' starts.');
});
M.on('resume', () => {
  startScore = Object.assign({}, M.st.score); G.a11y.title(TITLE + ': you against ' + oppName(gameOpp()));
  if (M.st.over) { endFx = { who: M.st.over.who, cells: M.st.over.cells || [], t0: K.t - 10 }; startScore = null; if (keepOf(M.st.keep).fresh) unlockOpen = true; else resultsOpen = true; }
});
M.on('think', () => { ghostJ = { x: geo().L.cx(3) }; G.sound.play('turn'); say(JULI + ' is thinking.'); });
M.on('decided', (e) => { if (e.by === 'juli' || e.by === 'forced') { moveLog.push({ board: G.copy(M.st.board), read: lastRead && lastRead.read, depth: lastRead && lastRead.depth, readMs: lastRead && lastRead.ms, ms: M.thinking ? Math.round(performance.now() - M.thinking.t0) : null, move: e.move, by: e.by, tries: e.tries, index: e.index, big: !!e.big, opp: gameOpp() }); if (moveLog.length > 200) moveLog.shift(); } });
M.on('stuck', () => { ghostJ = null; G.sound.play('error'); say(M.stuck && M.stuck.kind === 'nobig' ? 'The Bigger brain is off: turn it on in Settings, Models and downloads, or play ' + JULI + ' instead.' : stuckText() + '. Ask ' + JULI + ' again.'); });
M.on('move', (e) => { say((e.who === 1 ? 'You dropped' : JULI + ' dropped') + ' a disc in column ' + NAMES[e.move] + '.'); });
M.on('turn', (who) => { if (who === 1) say('Your turn.'); });
M.on('end', (over) => {
  endFx = { who: over.who, cells: over.cells || [], t0: K.t }; G.hot(3200);
  const tl = G.timeline(), gno = M.st.games;
  tl.call(() => G.sound.play(over.who === 1 ? 'win' : over.who === 2 ? 'lose' : 'draw'), { at: 140 });
  if (over.who === 1) tl.call(() => { const W = K.W, H = K.H, cols = [C_YOU, C_JULI, '#fff4d6', K.lighten(C_BOARD, 0.35), '#7ee0ff'];
    G.confetti(W * 0.1, H * 0.98, { n: 55, colors: cols, angle: -Math.PI / 2 + 0.3, spread: 0.6, power: 2100 });
    G.confetti(W * 0.9, H * 0.98, { n: 55, colors: cols, angle: -Math.PI / 2 - 0.3, spread: 0.6, power: 2100 }); }, { at: 420 });
  if (over.who === 1) tl.call(() => G.confetti(K.W / 2, -20, { n: 45, colors: [C_YOU, C_JULI, '#fff4d6', '#7ee0ff'], angle: Math.PI / 2, spread: 2.6, power: 260 }), { at: 820 });
  if (over.who === 2) tl.call(() => { const L = geo().L; for (const [r, c] of over.cells) G.sparks(L.cx(c), L.cy(r), { n: 8, color: C_JULI, power: 260 }); }, { at: 380 });
  const earned = keepOf(M.st.keep).fresh;   // the run's 10th win: the unlock card (and the big burst) instead of the results card
  tl.call(() => { if (M.st.over && M.st.games === gno && !M.clearing) { if (earned) { unlockOpen = true; G.celebrate({ colors: ['#ffd76a', '#fff4d6', C_YOU, C_JULI, '#7ee0ff'] }); G.sound.play('win'); } else resultsOpen = true; } }, { at: G.reduced ? 700 : 1500 }).play();   // not when a new game came first
  say(over.who === 1 ? WIN_TEXT + ' Four in a row.' : over.who === 2 ? JULI_WIN_TEXT + '. Four in a row.' : 'A draw: the board is full.');
  if (earned) say('New opponent unlocked: you beat ' + JULI + ' ' + UNLOCK_AT + ' times in a row.');
});
/** the unlock card is done with (its action, or Play again): it does not show again */
function unlockSeen() { M.st.keep = Object.assign({}, M.st.keep, { fresh: false }); M.save(); unlockOpen = false; }
/** the person picks an opponent (after the unlock): the Bigger brain only when it is downloaded and on (else say so and stay on Juli);
 *  a new game starts with it */
function chooseOpp(id) {
  const k = keepOf(M.st.keep);
  if (!k.unlocked) return;
  const apply = () => {
    menuOpen = false;
    if (k.opp === id && gameOpp() === id) return;
    M.st.keep = Object.assign({}, M.st.keep, { opp: id }); M.save();
    K.toast('Now playing ' + oppName(id), { icon: id === 'big' ? 'bolt' : 'sparkle', tone: 'good' }); say('Now playing ' + oppName(id) + '.');
    newGame();
  };
  if (id !== 'big') return apply();
  checkBig().then((ok) => {
    if (ok) { bigAsked = false; return apply(); }
    bigAsked = true;   // the menu says it plainly under the choices; the game stays on Juli
    K.toast('Needs the Bigger brain first', { tone: 'warn', ms: 3200 }); say(BIG + ' needs the Bigger brain: turn it on in Settings, Models and downloads. You play ' + JULI + ' until then.');
  });
}
let bigAsked = false;   // the person asked for the Bigger brain while it was off (the menu's note)
/** the Bigger brain gave no move (stopped, or turned off): the rest of this game, and the next ones, against Juli on her own model */
function juliInstead() {
  M.st.keep = Object.assign({}, M.st.keep, { opp: 'juli' }); M.st.opp = 'mixed'; M.save();
  say('Now playing ' + JULI + '.'); M.askAgain();
}

/** for automated tests: where the board is (screen coordinates in the app), the screen's state, the game's last read and Juli's moves */
window.__c4 = { geo: () => { const L = geo().L; return { ix: L.ix, iy: L.iy, cell: L.cell, x: L.x, y: L.y, w: L.w, h: L.h }; },
  screen: () => ({ resultsOpen, againPill, menuOpen, busyNew, unlockOpen, clearing: !!clearing, anim: !!anim, stuck: M.stuck ? M.stuck.kind : null, opp: gameOpp(), bigOK }),
  keep: () => keepOf(M.st.keep), lastRead: () => lastRead, moves: () => moveLog.slice(), board: () => G.copy(M.st.board), hints: GAME_HINTS };

function setup() {
  K.setup({ mode: 'dark', accent: C_BOARD });
  // a game saved by the first version of this design (3.9) goes on as it was (its level is dropped: Juli always plays her best)
  M.start({ introMs: 600 });
  G.a11y.title(TITLE + ': you against ' + oppName(gameOpp()));
  checkBig();
  K.scene('play', drawPlay);
}

function newGame() {
  if (busyNew) return; busyNew = true; resultsOpen = false; againPill = false; unlockOpen = false;
  if (M.st && !M.st.over && M.st.moves > 0) { M.st.keep = afterQuit(M.st.keep, gameOpp(), true); M.save(); }   // a game left half-way ends a run of wins
  if (endFx) endFx.out = K.t;   // the four's light goes out as their discs fall
  // the game that was on stops at once (Juli's turn, a disc still falling), the discs clear out, then the new game starts
  M.newGame({ clear: clearBoard }).then(() => { busyNew = false; });
}

// ===== DRAWING =====
function drawPlay() {
  const g = geo(), L = g.L, W = K.W, st = M.st, th = M.thinking;
  G.backdrop({ top: '#1d1442', bottom: '#08060f', glows: [{ x: 0.5, y: 0.45, r: 0.7, color: C_BOARD, a: 0.3 }, { x: 0.95, y: 1.0, r: 0.55, color: '#ff9f5a', a: 0.1 }], vignette: 0.5 });
  if (K.ptr.pressed) touched = true;

  // the bottom bar, under the thumb: what Juli does (opens the menu), sound, the menu
  const tag = 'Juli plays to win', tw0 = K.measure(tag, 'subhead', { weight: 600 }) + 56;
  if (K.button('about', g.side, g.bar.y, tw0, 40, tag, { style: 'glass', icon: 'sparkle', role: 'subhead', r: 20 })) menuOpen = true;
  G.soundButton('sound', W - g.side - 70, g.bar.y + 20, 40);
  if (K.iconButton('menu', W - g.side - 20, g.bar.y + 20, 40, 'more', { style: 'glass' })) menuOpen = true;

  // the players
  const pw = Math.floor((W - 2 * g.side - 10) / 2), juliMood = st.over ? (st.over.who === 2 ? 'happy' : st.over.who === 1 ? 'sad' : 'idle') : th ? 'thinking' : 'idle';
  G.player('you', g.side, g.players.y, pw, g.players.h, { name: YOU, score: st.score.you, color: C_YOU, active: !st.over && st.turn === 1 });
  G.player('juli', W - g.side - pw, g.players.y, pw, g.players.h, { name: JULI, sub: gameOpp() === 'big' ? 'Bigger brain' : undefined, score: st.score.juli, color: C_JULI, active: !st.over && st.turn === 2, juli: true, mood: juliMood, align: 'right' });

  // the status line
  drawStatus(g, st, th);

  // the board, its discs (behind the face) and the light on it; it jolts a little when a disc lands
  const aim = G.aim('board', L, { mode: 'column', top: g.lane.y - L.cell * 0.6, bottom: L.y + L.h, enabled: M.canPlay() && !busyNew && !resultsOpen && !menuOpen, legal: (c) => st.board[0][c] === 0 });
  if (aim.press) touched = true;
  if (aim.drop != null && M.play(aim.drop)) { ghostP = null; }
  const j = G.joltOf('board');
  push(); translate(j.x, j.y);
  G.boardBack(L, { color: C_BOARD });
  drawDiscs(g, st);
  G.board(L, { style: 'holes', color: C_BOARD, hole: g.hole });
  drawLight(g, st, aim);
  pop();
  drawGhost(g, st, th, aim);
  drawFoot(g, st);

  if (!unlockOpen) G.fx();

  // Juli gave no move: the game says so and waits for the person ("Ask Juli again"); it never moves for her. With the Bigger brain
  // there is also "Play Juli instead" (her own model, for the rest of the game)
  if (M.stuck && !st.over && !menuOpen) {
    const two = gameOpp() === 'big', bw = two ? Math.min(176, (W - 2 * g.side - 10) / 2) : 200, bx = two ? W / 2 - bw - 5 : W / 2 - 100;
    if (G.button('askagain', bx, g.bar.y - 58, bw, 46, two ? 'Ask again' : 'Ask ' + JULI + ' again', { icon: 'refresh', color: K.lighten(C_BOARD, 0.25) })) M.askAgain();
    if (two && G.button('juliinstead', W / 2 + 5, g.bar.y - 58, bw, 46, 'Play ' + JULI + ' instead', { style: 'soft', icon: 'sparkle', color: C_JULI })) juliInstead();
  }
  // the end of a game: the results card (or, while the person looks at the board, a Play again button)
  if (st.over && againPill && !resultsOpen && !unlockOpen) {
    if (G.button('again2', W / 2 - 90, g.bar.y - 58, 180, 46, 'Play again', { icon: 'refresh', color: st.over.who === 2 ? C_JULI : C_YOU })) newGame();
  }
  const outcome = st.over ? (st.over.who === 1 ? 'win' : st.over.who === 2 ? 'lose' : 'draw') : 'draw', opp = gameOpp();
  const act = G.results('end', { open: !!(st.over && resultsOpen && !unlockOpen), outcome, title: outcome === 'win' ? WIN_TEXT : outcome === 'lose' ? JULI_WIN_TEXT : 'Draw',
    sub: outcome === 'win' ? 'Four in a row in ' + st.moves + ' moves' : outcome === 'lose' ? oppName(opp) + ' made four in a row. Your revenge?' : 'The board is full: nobody wins',
    color: outcome === 'win' ? C_YOU : outcome === 'lose' ? C_JULI : K.lighten(C_BOARD, 0.3), score: st.score, prev: startScore, names: { you: YOU, juli: JULI },
    colors: { you: C_YOU, juli: C_JULI }, streak: st.streak, progress: progressOf(st.keep, opp), note: HONEST });
  if (act === 'again') newGame();
  else if (act === 'board') { resultsOpen = false; againPill = true; }
  // the run's 10th win: the unlock (the choice of opponent), celebrated once; it stays earned on this phone
  const ua = G.unlock('unlock', { open: !!(st.over && unlockOpen), title: 'New opponent unlocked!', icon: 'trophy', action: 'Choose your opponent', again: 'Play again',
    sub: 'You beat ' + JULI + ' ' + UNLOCK_AT + ' times in a row. Now you choose who you play: ' + JULI + ', or ' + BIG + '.' });
  if (unlockOpen) G.fx();   // the confetti flies over the card
  if (ua === 'action') { unlockSeen(); resultsOpen = false; againPill = true; checkBig(); menuOpen = true; }
  else if (ua === 'again') { unlockSeen(); newGame(); }

  menuOpen = K.sheet('menu', menuOpen, Math.min(K.H - 40, menuHeight(st) + g.bot), drawMenu);
  accessibility(g, st);
}

let lastStatus = '';
function drawStatus(g, st, th) {
  const W = K.W, y = g.status.y;
  let text = '', col = K.C.text;
  if (M.clearing) text = 'New game';
  else if (M.stuck && !st.over) { text = stuckText(); col = '#ffb36b'; }
  else if (st.over && !M.animating) text = st.over.who === 1 ? WIN_TEXT : st.over.who === 2 ? JULI_WIN_TEXT : 'A draw: the board is full';
  else if (M.animating && lastStatus) text = lastStatus;   // a disc is falling: the line changes when it lands
  else if (th || st.turn === 2) text = th && performance.now() - th.t0 > (gameOpp() === 'big' ? 20000 : 6000) ? JULI + ' is getting ready' : JULI + ' is thinking';
  else text = st.moves ? 'Your turn' : 'Your turn: tap a column';
  lastStatus = text;
  if (st.over && !M.animating && !M.clearing) col = st.over.who === 1 ? C_YOU : st.over.who === 2 ? C_JULI : K.C.text;
  const tw = K.text(text, W / 2 - (th ? 12 : 0), y, 'headline', col, { align: 'center', weight: 700 });
  if (th) for (let i = 0; i < 3; i++) {   // three dots that wave (a fixed width: the text never jitters)
    const a = G.reduced ? 0.7 : 0.35 + 0.65 * Math.max(0, Math.sin(K.t * 6 - i * 0.8));
    K.circle(W / 2 + tw / 2 - 6 + i * 8, y - 5 - (G.reduced ? 0 : 2 * Math.max(0, Math.sin(K.t * 6 - i * 0.8))), 2.4, { fill: K.alpha(C_JULI, a) });
  }
}

function drawDiscs(g, st) {
  const L = g.L, r = g.disc;
  if (clearing) {
    for (const d of clearing) G.piece(L.cx(d.c), d.body ? d.body.y : d.y, r, colorOf(d.who), { shadow: false });
    return;
  }
  for (let row = 0; row < ROWS; row++) for (let c = 0; c < COLS; c++) {
    const v = st.board[row][c]; if (!v) continue;
    if (anim && anim.row === row && anim.c === c) continue;
    G.piece(L.cx(c), L.cy(row), r, colorOf(v), { shadow: false });
  }
  if (anim) { const s = anim.body.squash || 0; G.piece(L.cx(anim.c), anim.body.y, r, colorOf(anim.who), { shadow: false, sx: 1 + 0.07 * s, sy: 1 - 0.1 * s }); }
}

/** light on the board: a landing flash, the column under the finger with where the disc will land, the winning four */
function drawLight(g, st, aim) {
  const L = g.L;
  if (landFx) { const k = (K.t - landFx.t0) / 0.32; if (k >= 1) landFx = null; else G.glow(L.cx(landFx.c), L.cy(landFx.row), L.cell * 0.75, colorOf(landFx.who), 0.45 * (1 - k)); }
  if (aim.hover != null && M.canPlay()) {
    const c = aim.hover, x = L.ix + c * L.cell;
    K.with((ctx) => {
      ctx.globalCompositeOperation = 'lighter';
      const gr = ctx.createLinearGradient(0, L.y, 0, L.y + L.h); gr.addColorStop(0, K.alpha(C_YOU, 0.28)); gr.addColorStop(1, K.alpha(C_YOU, 0.05));
      ctx.fillStyle = gr; K.pathRR(ctx, x + 2, L.y + 4, L.cell - 4, L.h - 8, L.cell * 0.3); ctx.fill();
    });
    const row = dropRow(st.board, c);
    if (row >= 0) K.circle(L.cx(c), L.cy(row), g.hole - 3, { fill: 'none', stroke: K.alpha(C_YOU, 0.55 + 0.35 * K.pulse(6)), sw: 2.5 });
  }
  if (endFx && endFx.out && K.t - endFx.out > 0.25) endFx = null;
  if (endFx && endFx.cells.length) {
    const out = endFx.out ? Math.max(0, 1 - (K.t - endFx.out) / 0.25) : 1;
    const k = Math.min(1, (K.t - endFx.t0) / 0.45), col = colorOf(endFx.who), pulse = G.reduced ? 0.6 : 0.5 + 0.5 * Math.sin((K.t - endFx.t0) * 5.5);
    for (const [r, c] of endFx.cells) G.glow(L.cx(c), L.cy(r), L.cell * (0.85 + 0.15 * pulse), col, (0.35 + 0.35 * pulse) * k * out);
    const pts = endFx.cells.map(([r, c]) => [L.cx(c), L.cy(r)]);
    if (pts.length >= 2) K.with((ctx) => {   // a band of light through the four, drawn on along the line
      const a = pts[0], b = pts[pts.length - 1], e = K.ease.outCubic(k);
      ctx.globalAlpha *= out; ctx.globalCompositeOperation = 'lighter'; ctx.lineCap = 'round';
      ctx.strokeStyle = K.alpha(col, 0.28 + 0.2 * pulse); ctx.lineWidth = L.cell * 0.34;
      ctx.beginPath(); ctx.moveTo(a[0], a[1]); ctx.lineTo(a[0] + (b[0] - a[0]) * e, a[1] + (b[1] - a[1]) * e); ctx.stroke();
      ctx.strokeStyle = K.alpha('#ffffff', 0.5 + 0.3 * pulse); ctx.lineWidth = Math.max(2, L.cell * 0.06);
      ctx.beginPath(); ctx.moveTo(a[0], a[1]); ctx.lineTo(a[0] + (b[0] - a[0]) * e, a[1] + (b[1] - a[1]) * e); ctx.stroke();
    });
    if (K.t - endFx.t0 < 2.5) G.hot(200);   // 60 fps while the four light up; the slow pulse after that is fine at 30
  }
}

/** the ghost disc in the lane above the board: yours under your finger; Juli's wanders while she thinks, then glides to her column */
let ghostP = null;
function drawGhost(g, st, th, aim) {
  const L = g.L, y0 = g.lane.y, r = g.disc;
  if (anim || clearing || st.over) return;
  if (st.turn === 2 && (th || ghostJ)) {
    if (!ghostJ) ghostJ = { x: L.cx(3) };
    if (ghostJ.target == null && !G.reduced) { const t = K.t; ghostJ.x = L.cx(3) + L.cell * (2.1 * Math.sin(t * 1.25) + 0.55 * Math.sin(t * 3.1 + 1)); ghostJ.x = Math.max(L.cx(0), Math.min(L.cx(COLS - 1), ghostJ.x)); }
    const gy = y0 + (G.reduced ? 0 : 2 * Math.sin(K.t * 3));
    G.piece(ghostJ.x, gy, r, C_JULI, { alpha: 0.92 }); K.circle(ghostJ.x, gy, r + 3, { fill: 'none', stroke: 'rgba(255,255,255,0.4)', sw: 1.5 });
    return;
  }
  if (!M.canPlay()) return;
  if (aim.hover != null) {
    const tx = L.cx(aim.hover); ghostP = ghostP == null ? tx : K.approach(ghostP, tx, 30);
    G.piece(ghostP, y0, r, C_YOU, { alpha: 0.95 });
    K.circle(ghostP, y0, r + 3, { fill: 'none', stroke: 'rgba(255,255,255,0.5)', sw: 1.5 });
  } else if (!touched && st.games <= 1 && !st.moves) {   // the first move of the first game: a disc bobs over the middle, pointing down
    const b = G.reduced ? 0 : Math.abs(Math.sin(K.t * 2.4)) * 6;
    G.piece(L.cx(3), y0 - b, r, C_YOU, { alpha: 0.55 });
    K.icon('chevronDown', L.cx(3), y0 + r + 12 - b * 0.4, 18, K.alpha('#ffffff', 0.7), { weight: 2.6 });
  }
}

function drawFoot(g, st) {
  const y = Math.min(g.bar.y - 14, g.foot);
  if (M.stuck && !st.over && M.stuck.kind === 'nobig') return K.text('Turn it on in Settings › Models & downloads, or play ' + JULI, K.W / 2, Math.min(y, g.bar.y - 72), 'footnote', '#ffb36b', { align: 'center', maxW: K.W - 32 });
  if (st.over || M.stuck) return;
  if (gameOpp() === 'big') K.text('Her moves take longer: she reads the board more deeply', K.W / 2, y, 'footnote', K.alpha(C_JULI, 0.85), { align: 'center', maxW: K.W - 32 });   // the Bigger brain (her card says so)
  else if (st.games <= 2) K.text('Four in a row across, down or diagonally wins', K.W / 2, y, 'footnote', K.C.text3, { align: 'center', maxW: K.W - 32 });
}

// the menu: what Juli does, the opponent (once earned; before that, the run toward it), sound, a new game, how to play
const quitEndsRun = (st) => { const k = keepOf(st.keep); return !k.unlocked && k.run > 0 && !st.over && st.moves > 0 && gameOpp() === 'juli'; };
const bigNote = () => bigAsked && !bigOK;
function menuHeight(st) { const u = keepOf(st.keep).unlocked; return 404 + (u ? 136 + (bigNote() ? 40 : 0) : 34) + (quitEndsRun(st) ? 20 : 0); }
function drawMenu(x, y, w, h, close) {
  const p = 20, st = M.st, k = keepOf(st.keep);
  K.text(TITLE, x + p, y + 46, 'title3', K.C.text, { weight: 800, family: 'ROUNDED' });
  K.text('You against ' + oppName(gameOpp()), x + p, y + 68, 'subhead', K.C.text2, { maxW: w - 2 * p });
  K.text(HONEST, x + p, y + 104, 'subhead', K.C.text, { weight: 700, maxW: w - 2 * p });
  K.para(GAME_HINTS ? 'Before each of her moves the game looks many moves ahead and tells her where each column leads. The choice is hers.' : 'She reads the board herself and chooses.',
    x + p, y + 124, w - 2 * p, 'footnote', K.C.text2, { maxLines: 3 });
  let yy = y + 178;
  if (k.unlocked) {   // the choice of opponent, earned: Juli, or Juli with the Bigger brain (only when it is downloaded and on)
    K.text('OPPONENT', x + p, yy + 4, 'caption', K.C.text3, { weight: 700 });
    yy += 14;
    for (const r of opponentRows(st.keep, bigOK, JULI)) {
      const row = K.listRow('opp-' + r.id, x + 8, yy, w - 16, 58, { title: r.title, sub: r.sub, icon: r.id === 'big' ? 'bolt' : 'sparkle', iconColor: r.id === 'big' ? (r.can ? '#7a4cf0' : K.C.text3) : C_JULI, r: 14 });
      if (r.on) K.icon('check', x + w - 32, yy + 29, 20, C_JULI, { weight: 2.8 });
      if (row.tap) chooseOpp(r.id);
      yy += 60;
    }
    if (bigNote()) {   // asked for while it is off: what it needs, plainly; she stays on Juli
      K.para(BIG + ' needs the Bigger brain: turn it on in Settings › Models & downloads. Until then you play ' + JULI + '.', x + p, yy - 4, w - 2 * p, 'footnote', '#ffb36b', { maxLines: 2 });
      yy += 40;
    }
    yy += 2;
  } else {   // not yet: the run toward it
    K.icon('lock', x + p + 7, yy + 11, 15, K.C.text3, { weight: 2.2 });
    K.text('Win ' + UNLOCK_AT + ' in a row to unlock a new opponent (' + Math.min(k.run, UNLOCK_AT - 1) + ' of ' + UNLOCK_AT + ')', x + p + 22, yy + 16, 'footnote', K.C.text2, { maxW: w - 2 * p - 22 });
    yy += 34;
  }
  const s = K.listRow('snd', x + 8, yy, w - 16, 52, { title: 'Sound', icon: G.sound.on ? 'sound' : 'mute', iconColor: C_BOARD, toggle: G.sound.on, r: 14 });
  if (s.toggle !== G.sound.on) G.sound.on = s.toggle;
  yy += 66;
  if (G.button('newgame', x + p, yy, w - 2 * p, 48, 'New game', { style: 'soft', icon: 'refresh', color: K.lighten(C_BOARD, 0.25) })) { close(); newGame(); }
  yy += 64;
  if (quitEndsRun(st)) { K.text('A new game now ends your run of ' + k.run + (k.run === 1 ? ' win' : ' wins'), x + w / 2, yy - 2, 'footnote', '#ffb36b', { align: 'center', maxW: w - 2 * p }); yy += 20; }
  K.para('Drop discs into the columns: tap a column, or hold and slide to aim, then let go. Four in a row across, down or diagonally wins.', x + p, yy, w - 2 * p, 'footnote', K.C.text3, { maxLines: 3 });
}

// a screen reader: what happened (G.a11y.say in the match's events) and buttons for the columns and the rest
function accessibility(g, st) {
  const can = M.canPlay() && !resultsOpen && !menuOpen && !busyNew && !unlockOpen, list = [];
  for (let c = 0; c < COLS; c++) {
    const free = st.board.reduce((n, row) => n + (row[c] === 0 ? 1 : 0), 0);
    list.push({ id: 'col' + c, label: 'Drop a disc in column ' + NAMES[c] + (free ? ' (' + free + ' free)' : ' (full)'), disabled: !can || !free, press: () => M.play(c) });
  }
  if (M.stuck && !st.over) list.push({ id: 'askagain', label: stuckText() + ': ask ' + JULI + ' again', press: () => M.askAgain() });
  if (M.stuck && !st.over && gameOpp() === 'big') list.push({ id: 'juliinstead', label: 'Play ' + JULI + ' instead (her own model)', press: juliInstead });
  if (st.over && unlockOpen) {
    list.push({ id: 'unlockchoose', label: 'New opponent unlocked: choose your opponent', press: () => { unlockSeen(); resultsOpen = false; againPill = true; checkBig(); menuOpen = true; } });
    list.push({ id: 'unlockagain', label: 'Play again', press: () => { unlockSeen(); newGame(); } });
  }
  for (const r of opponentRows(st.keep, bigOK, JULI)) list.push({ id: 'opp-' + r.id, label: 'Opponent: ' + r.title + (r.on ? ' (playing now)' : r.can ? '' : ' (needs the Bigger brain: Settings, Models and downloads)'), press: () => chooseOpp(r.id) });
  if (st.over && !unlockOpen) list.push({ id: 'again', label: 'Play again', press: newGame });
  list.push({ id: 'new', label: 'New game', press: newGame });
  list.push({ id: 'sound', label: G.sound.on ? 'Sound: on (turn off)' : 'Sound: off (turn on)', press: () => G.sound.toggle() });
  G.a11y.controls(list);
}

function draw() { K.render(); }
